import { doc, getDoc, Timestamp, updateDoc } from "firebase/firestore";
import { Html5QrcodeScanner } from "html5-qrcode";
import { useEffect, useRef, useState } from "react";
import { db } from "../firebase";

const ScanQR = () => {

    const [scanResult, setScanResult] = useState("");
    const [status, setStatus] = useState("");
    const [loading, setLoading] = useState(false);
    const scannerRef = useRef(null);

    useEffect(() => {
        if (!scannerRef.current) return;

        const scanner = new Html5QrcodeScanner(
            "qr-reader",
            { fps: 10, qrbox: { width: 250, height: 250 } },
            false
        );

        const onScanSuccess = async (decodedText) => {
            if (loading) return;
            setLoading(true);

            try {
                const studentRef = doc(db, "students", decodedText);
                const snap = await getDoc(studentRef);

                if (!snap.exists()) {
                    setStatus("❌ Invalid or fake QR");
                    setLoading(false);
                    return;
                }

                const data = snap.data();

                if (data.used === true) {
                    setStatus("⚠️ Pass already used");
                    setLoading(false);
                    return;
                }

                await updateDoc(studentRef, {
                    used: true,
                    lastScanAt: Timestamp.now()
                });

                setScanResult(data.name);
                setStatus("✅ Entry allowed");

            } catch (err) {
                console.error(err);
                setStatus("❌ Scan error");
            }

            setTimeout(() => {
                setLoading(false);
            }, 1500);
        };

        scanner.render(onScanSuccess, (error) => {
            console.warn(error);
        });

        return () => {
            scanner.clear();
        };
    }, [loading]);

    return (
        <div className="container mt-4">
            <h4 className="text-center mb-3">Scan Campus Pass</h4>

            <div id="qr-reader" ref={scannerRef} style={{ width: "100%" }}></div>

        {status && (
            <div
            className="alert mt-3 text-center"
            style={{
                background:
                status.includes("allowed")
                    ? "#d4edda"
                    : "#f8d7da"
            }}
            >
            {status}
            </div>
        )}

        {scanResult && (
            <p className="text-center mt-2">
            Student : <strong>{scanResult}</strong>
            </p>
        )}
        </div>
    );
};

export default ScanQR;
