import { useEffect, useState } from "react";
import {
    collection,
    onSnapshot,
    query,
    orderBy,
    doc,
    deleteDoc,
    updateDoc
    } from "firebase/firestore";
    import { db } from "../firebase";

    const StudentsList = () => {

    const [students, setStudents] = useState([]);
    const [search, setSearch] = useState("");

    useEffect(() => {
        const q = query(
        collection(db, "students"),
        orderBy("createdAt", "desc")
        );

        const unsub = onSnapshot(q, (snap) => {
        const list = snap.docs.map(d => ({
            id: d.id,
            ...d.data()
        }));
        setStudents(list);
        });

        return () => unsub();
    }, []);

    const filtered = students.filter(s =>
        s.name?.toLowerCase().includes(search.toLowerCase()) ||
        s.email?.toLowerCase().includes(search.toLowerCase()) ||
        s.roll?.toLowerCase().includes(search.toLowerCase())
    );

    // ✅ delete student
    const handleDelete = async (id) => {
        if (!window.confirm("Delete this student?")) return;
        await deleteDoc(doc(db, "students", id));
    };

    // ✅ reset pass
    const handleReset = async (id) => {
        await updateDoc(doc(db, "students", id), {
        used: false,
        lastScanAt: null
        });
    };

    // ✅ export csv
    const exportCSV = () => {
        const headers = ["Name", "Email", "Roll", "Status", "Last Scan"];
        const rows = filtered.map(s => [
        s.name || "",
        s.email || "",
        s.roll || "",
        s.used ? "Used" : "Not Used",
        s.lastScanAt
            ? new Date(s.lastScanAt.seconds * 1000).toLocaleString()
            : ""
        ]);

        let csv =
        headers.join(",") +
        "\n" +
        rows.map(r => r.map(v => `"${v}"`).join(",")).join("\n");

        const blob = new Blob([csv], { type: "text/csv" });
        const url = URL.createObjectURL(blob);

        const a = document.createElement("a");
        a.href = url;
        a.download = "students-pass-list.csv";
        a.click();
        URL.revokeObjectURL(url);
    };

    return (
        <div className="container mt-4">

        <div className="d-flex justify-content-between align-items-center mb-2">
            <h4 className="mb-0">Students / Pass List</h4>

            <button
            className="btn btn-sm btn-outline-primary"
            onClick={exportCSV}
            >
            Export CSV
            </button>
        </div>

        <input
            className="form-control mb-3"
            placeholder="Search by name, email or roll"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
        />

        <div className="table-responsive">
            <table className="table table-bordered table-sm align-middle">
            <thead className="table-light">
                <tr>
                <th>#</th>
                <th>Name</th>
                <th>Email</th>
                <th>Roll</th>
                <th>Status</th>
                <th>Last Scan</th>
                <th>Actions</th>
                </tr>
            </thead>

            <tbody>
                {filtered.length === 0 && (
                <tr>
                    <td colSpan="7" className="text-center text-muted">
                    No records
                    </td>
                </tr>
                )}

                {filtered.map((s, i) => (
                <tr key={s.id}>
                    <td>{i + 1}</td>
                    <td>{s.name}</td>
                    <td>{s.email}</td>
                    <td>{s.roll}</td>
                    <td>
                    {s.used ? (
                        <span className="badge bg-danger">Used</span>
                    ) : (
                        <span className="badge bg-success">Not Used</span>
                    )}
                    </td>
                    <td>
                    {s.lastScanAt
                        ? new Date(
                            s.lastScanAt.seconds * 1000
                        ).toLocaleString()
                        : "-"}
                    </td>
                    <td className="d-flex gap-1">
                    <button
                        className="btn btn-warning btn-sm"
                        onClick={() => handleReset(s.id)}
                    >
                        Reset
                    </button>

                    <button
                        className="btn btn-danger btn-sm"
                        onClick={() => handleDelete(s.id)}
                    >
                        Delete
                    </button>
                    </td>
                </tr>
                ))}
            </tbody>
            </table>
        </div>

        </div>
    );
};

export default StudentsList;
