import { doc, getDoc, setDoc, Timestamp } from 'firebase/firestore';
import { QRCodeCanvas } from 'qrcode.react';
import { useRef, useState } from 'react';
import '../App.css';
import { db } from '../firebase';
import '../index.css';
import '../styles.css';

const GenerateQR = () => {

    const [studentName, setStudentName] = useState('');
    const [studentEmail, setStudentEmail] = useState('');
    const [studentRoll, setStudentRoll] = useState('');

    const [userId, setUserId] = useState('');
    const [showQR, setShowQR] = useState(false);
    const [showToast, setShowToast] = useState(false);

    const qrRef = useRef(null);

    const handleGenerate = async () => {
        try {
        const name = studentName.trim();
        const email = studentEmail.trim().toLowerCase();
        const roll = studentRoll.trim();

        if (!name || !email || !roll) {
            alert("All fields required");
            return;
        }

        const safeId = email.replace(/[.#$[\]]/g, "_");

        const studentRef = doc(db, "students", safeId);

        const snap = await getDoc(studentRef);

        if (snap.exists()) {
            alert("Student already registered");
            return;
        }

        await setDoc(studentRef, {
            name,
            email,
            roll,
            createdAt: Timestamp.now()
        });

        setUserId(safeId);
        setShowQR(true);
        setShowToast(true);

        } catch (err) {
        console.error(err);
        alert("Something went wrong while generating QR");
        }
    };

    return (
        <div className="container mt-5 d-flex justify-content-center">
        <div className="card shadow-lg p-4" style={{ maxWidth: '500px', width: '100%' }}>

            <div className="hero d-flex align-items-center gap-3 mb-3">
            <div className="hero-badge d-flex align-items-center justify-content-center">🎓</div>
            <div>
                <h4 className="mb-0">Generate Access Pass</h4>
                <small className="text-muted">Quickly create and save a QR code</small>
            </div>
            </div>

            <input
            type="text"
            className="form-control mb-2"
            placeholder="Student Name"
            value={studentName}
            onChange={(e) => setStudentName(e.target.value)}
            />

            <input
            type="email"
            className="form-control mb-2"
            placeholder="Student Email"
            value={studentEmail}
            onChange={(e) => setStudentEmail(e.target.value)}
            />

            <input
            type="text"
            className="form-control mb-3"
            placeholder="Roll / Enrollment No"
            value={studentRoll}
            onChange={(e) => setStudentRoll(e.target.value)}
            />

            <button
            className="btn btn-primary w-100"
            onClick={handleGenerate}
            >
            Generate QR
            </button>

            {showQR && (
            <div className="text-center mt-3">
                <div className="qr-animate">
                <div ref={qrRef} className="qr-wrapper mx-auto p-3">
                    <QRCodeCanvas value={userId} size={220} />
                </div>
                <div className="ring" aria-hidden="true"></div>
                </div>

                <p className="mt-2">
                <strong>Pass ID:</strong> {userId}
                </p>

                <div className="d-flex gap-2 justify-content-center mt-2">
                <button
                    className="btn btn-outline-secondary btn-sm"
                    onClick={() => {
                    navigator.clipboard?.writeText(userId);
                    }}
                >
                    📋 Copy ID
                </button>

                <button
                    className="btn btn-success btn-sm"
                    onClick={() => {
                    const canvas = qrRef.current?.querySelector('canvas');
                    if (canvas) {
                        const url = canvas.toDataURL('image/png');
                        const a = document.createElement('a');
                        a.href = url;
                        a.download = `campus-qr-${userId}.png`;
                        a.click();
                    }
                    }}
                >
                    ⬇️ Download
                </button>
                </div>
            </div>
            )}

            {showToast && (
            <div className="toast-success shadow-sm mt-3 mx-auto">
                <strong>Success</strong>
                <div className="small">QR generated and student saved</div>
            </div>
            )}

        </div>
        </div>
    );
};

export default GenerateQR;
